// Loop over all items
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // 'data' is the name of your binary property (from your screenshot)
  // We read the file buffer from n8n's internal storage
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  // Convert the buffer to a Base64 string and save it to a new JSON field
  item.json.audioBase64 = buffer.toString('base64');
}

return items;

