// نقرأ النص من أول عنصر
let raw = $input.first().json.text || $input.first().json.output || "";

// 1) إزالة أي Markdown مثل ```json أو ``` فقط
raw = raw.replace(/```json/gi, "")
         .replace(/```/g, "")
         .trim();

// 2) لو النص داخل Array أو فيه عناصر إضافية، نستخرج أول { ... }
const match = raw.match(/\{[\s\S]*\}/);
if (!match) {
  return {
    output: {
      error: "No JSON object found in text",
      raw
    }
  };
}

let jsonString = match[0];

// ⭐ إصلاح الأسطر الحقيقية داخل السلاسل النصية فقط
let fixed = "";
let inString = false;
let escaped = false;

for (let i = 0; i < jsonString.length; i++) {
  const ch = jsonString[i];

  if (!inString) {
    fixed += ch;
    if (ch === '"') inString = true;
  } else {
    if (escaped) {
      fixed += ch;
      escaped = false;
    } else {
      if (ch === "\\") {
        fixed += ch;
        escaped = true;
      } else if (ch === '"') {
        fixed += ch;
        inString = false;
      } else if (ch === "\n") {
        fixed += "\\n";   // ← إصلاح السطر
      } else if (ch === "\r") {
        // تجاهل CR
      } else {
        fixed += ch;
      }
    }
  }
}

// 4) محاولة التحويل إلى JSON
let parsed;
try {
  parsed = JSON.parse(fixed);
} catch (err) {
  return {
    output: {
      error: "Failed to parse JSON",
      message: err.message,
      raw: fixed
    }
  };
}

// 5) إرجاع JSON مضبوط داخل output
return {
  output: parsed
};

